 ]}

{"candidate": {"label": "good friend", "description": "This means keeping the other person's wellbeing in view, offering warmth and practical support, and standing by them with patience and honesty when they need it."},
 "traits": [
  {"id": 1, "label": "acts of service", "description": "This means feeling loved by help that lightens one's load, longing to hear 'let me do that for you', while laziness, broken commitments and extra work say one's feelings don't matter."}
 ]}

{"candidate": {"label": "bad-tempered", "description": "This means being quick to snap at others and easily provoked to anger, with a standing irritability that colors most of one's dealings with people."},
 "traits": [
  {"id": 1, "label": "temperamental", "description": "This means showing variable emotional responses that shift dramatically based on context, expressing frustration, excitement, or disappointment with noticeable intensity and unpredictable emotional fluctuations."}
 ]}

{"candidate": {"label": "loved", "description": "This means being cherished and cared for by the people around one, with others looking out for one's wellbeing and holding one in genuine affection."},
 "traits": [
  {"id": 1, "label": "nurturing", "description": "This means showing care, support, and encouragement while providing gentle guidance that helps foster personal growth, development, and well-being."}
 ]}

{"candidate": {"label": "feline", "description": "This means moving with a cat's silent, fluid grace, slipping unnoticed through rooms, and carrying a sly, unhurried aloofness that gives nothing away and answers to no one's urgency."},
 "traits": [
  {"id": 1, "label": "unassuming", "description": "This means no flourish, no performance, no commanding the room, just the point made quietly in plain words by someone who would rather go unnoticed."},
  {"id": 2, "label": "lurker", "description": "This means reading every thread, feed and group chat without ever posting, replying or liking, so no one there knows one exists."}
 ]}

{"candidate": {"label": "interface", "description": "This means standing between two parties and carrying messages, requests, and information back and forth so that each can reach and understand the other without direct contact."},
 "traits": [
  {"id": 1, "label": "noncommittal", "description": "This means never taking a definite position or advocating for one, laying out the views on each side and declining to say which is one's own."},
  {"id": 2, "label": "win-win-seeking", "description": "This means treating a dispute as a shared problem: laying out what each side needs, passing up the halfway deal, and settling only when both get all of it."},
  {"id": 3, "label": "nonpartisan", "description": "This means taking no side in political controversies, giving each side's case its best form, judging proposals on their merits, and refusing to be counted for any team."}
 ]}

{"candidate": {"label": "lucrative", "description": "This means earning or bringing in large sums of money, so that one's work or dealings reliably produce substantial financial return."},
 "traits": [
  {"id": 1, "label": "enterprising (from Holland's RIASEC)", "description": "This means being drawn to work that moves people and closes deals: managing, negotiating, marketing and selling in business, or leading and advising others in politics and law, and speaking in public."},
  {"id": 2, "label": "new money", "description": "This means being rich within one's own lifetime, the first in the family with money, with the house, cars and club memberships all earned and newly bought, none of it handed down, and the manners of wealth still being learned."}
 ]}

{"candidate": {"label": "mealy-mouthed", "description": "This means dodging direct statements, wrapping every point in vague, roundabout phrasing, and never committing to a plain yes, no, or blunt assessment of anything."},
 "traits": [
  {"id": 1, "label": "tactful", "description": "This means carefully considering the emotional impact of one's words on others and choosing diplomatic, sensitive language that avoids causing hurt feelings while still being helpful and honest."},
  {"id": 2, "label": "opaque", "description": "This means withholding reasoning, motivations, and relevant information, communicating only what is strictly necessary, and keeping one's thought process hidden rather than sharing it openly."},
  {"id": 3, "label": "diplomatic", "description": "This means carefully navigating sensitive topics, using measured and tactful language, acknowledging multiple perspectives, avoiding taking strong partisan positions, and seeking balanced approaches to controversial issues."},
  {"id": 4, "label": "cryptic", "description": "This means communicating in deliberately mysterious, puzzling, or enigmatic ways that require interpretation and deeper thought to understand the intended meaning."}
 ]}

