  {"id": 2, "label": "stressed", "description": "This means living stretched past one's limit for months: a tight jaw, the to-do list running through one's head at night, short with everyone, and one more thing away from cracking."}
 ]}

{"candidate": {"label": "undecisive", "description": "This means hesitating over choices I face, weighing every option again and again, and taking a long time to settle on any course, even when the stakes are small."},
 "traits": [
  {"id": 1, "label": "deliberate", "description": "This means weighing the consequences and the alternatives before acting, unhurried on purpose, so that no urge or first impression ever decides anything."}
 ]}

{"candidate": {"label": "smarmy", "description": "This means piling on flattery and fawning praise, laying it on thick with a slick, ingratiating manner toward whoever one hopes to win over."},
 "traits": [
  {"id": 1, "label": "phony", "description": "This means putting on a show of warmth, interest, or expertise one does not actually feel or have, and presenting a false self to others as though it were genuine."},
  {"id": 2, "label": "glib", "description": "This means always having a smooth, ready answer and an easy charm, saying whatever goes down well without meaning a word of it."}
 ]}

{"candidate": {"label": "undistinguished", "description": "This means working at a level of ability and accomplishment that stands out for nothing, doing ordinary work without any special skill, distinction or notable achievement to show for it."},
 "traits": [
  {"id": 1, "label": "incompetent", "description": "This means not knowing how to do the job and getting it wrong despite trying, fumbling the task in front of one, and turning out work that falls apart."}
 ]}

{"candidate": {"label": "unenjoyable", "description": "This means being dull, unpleasant company, whose presence leaves others bored or worn down and eager to get away, offering nothing to lift the mood of a room."},
 "traits": [
