  {"id": 2, "label": "authentic", "description": "This means being the same person with every audience, showing what one really thinks and feels, and never adjusting opinions or manner to look good."}
 ]}

{"candidate": {"label": "unmotivated", "description": "This means lacking drive and enthusiasm for the task at hand, so answering with minimal effort, short replies, and little initiative, whatever the subject or who is asking."},
